    /// y = A_q8_0 * x (quantized GEMV for Q8_0)
    /// F16-weight × F32-input GEMV. y[m] = W_f16[m, k] @ x_f32[k].
    /// Keeps full F32 input precision — use this for full-precision F16
    /// weights instead of the WMMA F16×F16 path (which converts the F32
    /// input to F16 first, losing ~13 bits of mantissa).
    pub fn gemv_f16_xf32(
        &mut self,
        weight: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel("gemv_f16_xf32", kernels::GEMV_F16_XF32_SRC, "gemv_f16_xf32")?;

        let w_ptr = weight.buf.as_ptr();
        let x_ptr = x.buf.as_ptr();
        let y_ptr = y.buf.as_ptr();
        let m_val = m as i32;
        let k_val = k as i32;

        let mut params: Vec<*mut c_void> = vec![
            &w_ptr as *const _ as *mut c_void,
            &x_ptr as *const _ as *mut c_void,
            &y_ptr as *const _ as *mut c_void,
            &m_val as *const _ as *mut c_void,
            &k_val as *const _ as *mut c_void,
        ];

        let blob_builder = || {
            let mut b = hip_bridge::KernargBlob::new();
            b.push_ptr(w_ptr); b.push_ptr(x_ptr); b.push_ptr(y_ptr);
            b.push_i32(m_val); b.push_i32(k_val);
            b
        };

        self.launch_maybe_blob(
            "gemv_f16_xf32",
            [m as u32, 1, 1], [32, 1, 1], 0, &mut params,
            blob_builder,
        )
    }

    /// DeepSeek V4 hash-routed MoE: GPU-side tid2eid lookup + score gather +
    /// softmax-normalize + route_scale multiply. Replaces the d2h+host+h2d
    /// round-trip in `ffn_hash_routed`.
